package com.sliit.eventsphere.entity;

import jakarta.persistence.*;
import java.time.LocalDateTime;

/**
 * A message an Organizer or Administrator writes by hand to the attendees
 * of one event.
 *
 * Every other notification in this system is generated by the system
 * reacting to something it did, so its wording is bounded by the code that
 * produces it. This one is free text written by a person and delivered to
 * every attendee's inbox, which is why it is the only thing here that
 * needs approving before it can be sent.
 *
 * The row outlives publication and is never edited afterwards. It is the
 * record of what was said, by whom, to how many people, and who approved
 * it - the notification rows it produced belong to their recipients and
 * are separate.
 */
@Entity
@Table(name = "announcements")
public class Announcement {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    /**
     * The event whose attendees are the audience.
     *
     * Note what is NOT stored: the recipient list. It is resolved when the
     * announcement is published, because a list captured while it was
     * still a draft would already be out of date by the time an
     * administrator got to it - people register and cancel in between.
     */
    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "event_id", nullable = false)
    private Event event;

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "author_id", nullable = false)
    private User author;

    @Column(nullable = false, length = 150)
    private String title;

    @Column(nullable = false, length = 1000)
    private String message;

    @Enumerated(EnumType.STRING)
    @Column(nullable = false, length = 20)
    private AnnouncementStatus status = AnnouncementStatus.DRAFT;

    @Column(name = "created_at", updatable = false)
    private LocalDateTime createdAt;

    @Column(name = "submitted_at")
    private LocalDateTime submittedAt;

    @Column(name = "decided_at")
    private LocalDateTime decidedAt;

    /**
     * The administrator who approved or rejected it.
     *
     * Not cascaded on delete: if the account goes, the decision still
     * happened - we simply can no longer name who made it.
     */
    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "decided_by")
    private User decidedBy;

    /**
     * Why it was turned down. Required by the schema for a REJECTED row,
     * because "rejected" with no reason is the thing that makes an author
     * resubmit the same text and get rejected again.
     */
    @Column(name = "reject_reason", length = 500)
    private String rejectReason;

    @Column(name = "published_at")
    private LocalDateTime publishedAt;

    /**
     * How many inboxes it reached, counted at the moment of publication.
     *
     * Stored rather than recomputed: asking how many people hold a place
     * on the event today answers a different question from how many
     * received this message when it went out.
     */
    @Column(name = "recipient_count")
    private Integer recipientCount;

    @PrePersist
    protected void onCreate() {
        createdAt = LocalDateTime.now();
    }

    public Announcement() {
    }

    public Long getId() {
        return id;
    }

    public void setId(Long id) {
        this.id = id;
    }

    public Event getEvent() {
        return event;
    }

    public void setEvent(Event event) {
        this.event = event;
    }

    public User getAuthor() {
        return author;
    }

    public void setAuthor(User author) {
        this.author = author;
    }

    public String getTitle() {
        return title;
    }

    public void setTitle(String title) {
        this.title = title;
    }

    public String getMessage() {
        return message;
    }

    public void setMessage(String message) {
        this.message = message;
    }

    public AnnouncementStatus getStatus() {
        return status;
    }

    public void setStatus(AnnouncementStatus status) {
        this.status = status;
    }

    public LocalDateTime getCreatedAt() {
        return createdAt;
    }

    public LocalDateTime getSubmittedAt() {
        return submittedAt;
    }

    public void setSubmittedAt(LocalDateTime submittedAt) {
        this.submittedAt = submittedAt;
    }

    public LocalDateTime getDecidedAt() {
        return decidedAt;
    }

    public void setDecidedAt(LocalDateTime decidedAt) {
        this.decidedAt = decidedAt;
    }

    public User getDecidedBy() {
        return decidedBy;
    }

    public void setDecidedBy(User decidedBy) {
        this.decidedBy = decidedBy;
    }

    public String getRejectReason() {
        return rejectReason;
    }

    public void setRejectReason(String rejectReason) {
        this.rejectReason = rejectReason;
    }

    public LocalDateTime getPublishedAt() {
        return publishedAt;
    }

    public void setPublishedAt(LocalDateTime publishedAt) {
        this.publishedAt = publishedAt;
    }

    public Integer getRecipientCount() {
        return recipientCount;
    }

    public void setRecipientCount(Integer recipientCount) {
        this.recipientCount = recipientCount;
    }

    /**
     * Whether the author may still change the text.
     *
     * Reads better than the status comparison at every call site, and
     * keeps one definition of "editable" rather than four. A submitted
     * announcement is frozen because an administrator is reading it; a
     * published one is frozen because people have already received it.
     */
    public boolean isEditable() {
        return status == AnnouncementStatus.DRAFT || status == AnnouncementStatus.REJECTED;
    }

    /** Whether it has actually reached anybody. */
    public boolean isPublished() {
        return status == AnnouncementStatus.PUBLISHED;
    }
}
